Lemma odescA_facts : forall d t v, odescA d t v ->
  exists r, find_opnd t v = Some ((d - 0x48680) / 52, r) /\ tg_operand t v = Some (v_span r) /\ v_value r = v /\
  0x48680 <= d /\ d + 52 <= 0x48680 + 64740 /\ d mod 4 = 0 /\ (d - 0x48680) mod 52 = 0 /\
  (forall m, tvis m -> fld ASEGS m d 4 v /\ fld ASEGS m (d + 4) 4 (v_first r) /\ fld ASEGS m (d + 8) 4 (v_count r) /\ gz m d 12) /\
  0 <= v < 2 ^ 32 /\ 0 <= v_first r /\ 0 <= v_count r /\ v_first r + v_count r <= Zlen SPANS /\
  spanA (0x25680 + 4 * v_first r) (v_span r) /\ Zlen (v_span r) = v_count r.
Proof.
