Lemma edescA_facts : forall d e v, edescA d e v ->
  exists r, find_ext e v = Some ((d - 0x5c2a0) / 28, r) /\ tg_ext e v = Some (v_span r) /\ v_value r = v /\
  0x5c2a0 <= d /\ d + 28 <= 0x5c2a0 + 14000 /\ d mod 4 = 0 /\ (d - 0x5c2a0) mod 28 = 0 /\
  (forall m, tvis m -> fld ASEGS m d 4 v /\ fld ASEGS m (d + 4) 4 (v_first r) /\ fld ASEGS m (d + 8) 4 (v_count r) /\ gz m d 28) /\
  0 <= v < 2 ^ 32 /\ 0 <= v_first r /\ 0 <= v_count r /\ v_first r + v_count r <= Zlen SPANS /\
